        "thai": "ภิกษุทั้งหลาย อริยสาวกในธรรมวินัยนี้ ละการฆ่าสัตว์ เว้นขาดจากการฆ่าสัตว์ เมื่อเว้นได้แล้ว ก็ชื่อว่าให้ความไม่มีภัย ความไม่มีเวร ความไม่เบียดเบียน แก่สัตว์ทั้งหลายนับไม่ถ้วน เมื่อให้แล้ว ตนเองก็ได้ส่วนของความไม่มีภัย ไม่มีเวร ไม่เบียดเบียน ที่ไม่มีประมาณเช่นกัน ภิกษุทั้งหลาย นี่คือทานข้อที่หนึ่ง เป็นมหาทาน รู้กันว่าเป็นของเลิศ เป็นของมีมานาน เป็นวงศ์ประเพณี เป็นของเก่าแก่ ไม่เคยถูกละเลย ไม่ถูกละเลยอยู่ และจะไม่ถูกละเลย สมณพราหมณ์ผู้รู้ไม่คัดค้าน และเป็นท่อธารบุญ ท่อธารกุศลข้อที่สี่ นำความสุขมาให้ เกื้อกูลต่อสวรรค์ มีผลเป็นสุข เป็นไปเพื่อสวรรค์ เป็นไปเพื่อสิ่งที่น่าปรารถนา น่าใคร่ น่าพอใจ เพื่อประโยชน์และความสุข",
