        "pali": "ปุนะ จะปะรัง ภิกขะเว อะริยะสาวะโก กาเมสุมิจฉาจารัง ปะหายะ กาเมสุมิจฉาจารา ปะฏิวิระโต โหติ\nกาเมสุมิจฉาจารา ปะฏิวิระโต ภิกขะเว อะริยะสาวะโก อะปะริมาณานัง สัตตานัง อะภะยัง เทติ อะเวรัง เทติ อัพยาพัชฌัง เทติ\nอะปะริมาณานัง สัตตานัง อะภะยัง ทัตวา อะเวรัง ทัตวา อัพยาพัชฌัง ทัตวา อะปะริมาณัสสะ อะภะยัสสะ อะเวรัสสะ อัพยาพัชฌัสสะ ภาคี โหติ\nอิทัง ภิกขะเว ตะติยัง ทานัง มะหาทานัง อัคคัญญัง รัตตัญญัง วังสัญญัง โปราณัง อะสังกิณณัง อะสังกิณณะปุพพัง นะ สังกิยะติ นะ สังกิยิสสะติ อัปปะฏิกุฏฐัง สะมะเณหิ พฺราหมะเณหิ วิญญูหิ\nอะยัง ภิกขะเว ฉัฏโฐ ปุญญาภิสันโท กุสะลาภิสันโท สุขัสสาหาโร โสวัคคิโก สุขะวิปาโก สัคคะสังวัตตะนิโก อิฏฐายะ กันตายะ มะนาปายะ หิตายะ สุขายะ สังวัตตะติ",
