        "pali": "ปุนะ จะปะรัง ภิกขะเว อะริยะสาวะโก มุสาวาทัง ปะหายะ มุสาวาทา ปะฏิวิระโต โหติ\nมุสาวาทา ปะฏิวิระโต ภิกขะเว อะริยะสาวะโก อะปะริมาณานัง สัตตานัง อะภะยัง เทติ อะเวรัง เทติ อัพยาพัชฌัง เทติ\nอะปะริมาณานัง สัตตานัง อะภะยัง ทัตวา อะเวรัง ทัตวา อัพยาพัชฌัง ทัตวา อะปะริมาณัสสะ อะภะยัสสะ อะเวรัสสะ อัพยาพัชฌัสสะ ภาคี โหติ\nอิทัง ภิกขะเว จะตุตถัง ทานัง มะหาทานัง อัคคัญญัง รัตตัญญัง วังสัญญัง โปราณัง อะสังกิณณัง อะสังกิณณะปุพพัง นะ สังกิยะติ นะ สังกิยิสสะติ อัปปะฏิกุฏฐัง สะมะเณหิ พฺราหมะเณหิ วิญญูหิ\nอะยัง ภิกขะเว สัตตะโม ปุญญาภิสันโท กุสะลาภิสันโท สุขัสสาหาโร โสวัคคิโก สุขะวิปาโก สัคคะสังวัตตะนิโก อิฏฐายะ กันตายะ มะนาปายะ หิตายะ สุขายะ สังวัตตะติ",
